  if value == "" {
    return "Environment name cannot be empty"
  }

  if !string_is_alphanumeric(value) {
    return "Environment name can only contain letters and numbers"
  }

  return "Environment name is valid"
}

# Helper function to check if a string contains only alphanumeric characters
function string_is_alphanumeric(value) {
  for i in range(0, len(value)):
